export const syllabusSources={1:'https://www.amac.org.cn/xwfb/tzgg/202606/P020260630399995319242.pdf',3:'https://www.amac.org.cn/xwfb/tzgg/202606/P020260630399995526911.pdf'};
export const examSource='https://www.amac.org.cn/fwdt/wyb/rygl/';
const courses=[];
function unit(title,subject,sections,scene,analogy,points){courses.push({title,subject,sections:sections.split(','),scene,analogy,points})}
unit('资金在哪个市场流动？',1,'1.1','同一家公司想筹钱：发行新股、交易已发行的股票、借一个月的钱，发生在不同类型的市场。分类要看期限、交易对象与发行环节。','像交通地图：道路按路线与用途分类，不是按车主身份分类。',[
['构成要素','金融市场由参与者、交易工具、交易机制等组成，连接资金供求。','判断一项金融市场安排时，首先需要看什么？','参与者、工具与交易机制','只有交易者年龄','只有办公楼大小','只有宣传海报'],
['发行与交易','一级市场涉及工具发行；二级市场涉及已发行工具的交易。二级市场的流动性也支持一级市场融资。','公司首次发行股票获得资金，属于哪个环节？','一级市场发行','二级市场买卖存量股票','投资者间转让基金份额','货币兑换'],
['期限分类','货币市场主要交易短期金融工具，资本市场主要服务中长期融资。短期不意味着无风险。','企业寻找短期资金周转，分析时更相关的分类是？','货币市场与资本市场的期限区别','公募管理人和托管人的职责区别','股东姓名分类','按广告播放次数分类'],
['金融功能','资金融通、风险配置、价格发现和提供流动性等功能共同支持实体经济。','二级市场交易便利，对企业融资有什么可能帮助？','提高流动性，支持投资者参与融资','直接消除企业经营风险','保证新股发行成功','代替所有企业生产']]);
unit('资产管理与基金发展',1,'1.2,2.3','你拥有资金但缺少专业能力，委托机构管理资产。不同资管形式的发展，与居民储蓄、机构需求、市场和监管演进有关。','把资产管理想成专业管家服务；基金只是服务的组织方式之一。',[
['受托管理','资产管理是按约定对受托资产进行管理，重要基础是受托责任与风险管理。','受托管理资产时，资产首先应按什么使用？','委托安排与适用规则','管理人个人喜好','员工私人账户余额','只按广告承诺'],
['资管范围','基金、信托、证券资管等安排有不同制度，不能把所有资产管理都等同于公募基金。','关于资产管理与基金的关系，哪项更准确？','基金是资产管理的重要形式之一','所有资管都是公募基金','私募不属于资管范畴','资管只包括银行存款'],
['发展脉络','学习公募、私募基金与私募资产管理计划的发展，应分别梳理制度沿革，不能混为同一条历史线。','梳理行业发展时，更合理的做法是？','分别看各类业务的制度与发展背景','把三类业务的规定混用','只记机构广告','忽略监管变化'],
['经济作用','基金连接储蓄与投资、支持资本形成和专业管理。具体行业规模与最新发展数据需要核对官方统计。','看到一份多年前的行业规模数字，应怎样处理？','核对统计日期、范围与官方更新','直接当成现在的规模','用来证明投资必赚','以个人感觉替代统计']]);
unit('基金分类：先问分类依据',1,'2.1,2.2','一只基金既可以是开放式、公募，也可以投资股票。几个标签回答不同问题，彼此不冲突。','像给一本书分类：装订方式、发行范围和内容主题是三种维度。',[
['不同维度','组织形式、募集方式、运作方式、投资对象是不同分类维度。','公募与股票基金能同时描述一只基金吗？','能，募集方式与投资对象是不同维度','不能，标签只能选一个','股票基金必然是私募','公募基金只投资债券'],
['开放与封闭','开放式与封闭式主要涉及份额与申赎等运作安排；并非按收益高低分类。','开放式基金与封闭式基金的区别，应主要从哪里理解？','份额与申赎运作安排','是否必定盈利','管理人姓名','投资者性别'],
['金融品种比较','基金份额、股票、债券和存款的法律关系、收益来源与风险不同。','买基金份额与持有某企业股票有什么区别？','份额对应集合投资权益，股票对应企业股权','两者都等于银行存款','基金份额必然有固定利息','股票没有企业经营风险'],
['运作关系','募集、投资、估值核算、披露、申赎和清算等环节由多个参与主体协作。','基金运作关系的正确认识是？','多个主体按职责协作','托管人独自完成全部投资决策','销售人员可任意改合同','投资者不需获取信息']]);
unit('规则冲突时，先看哪一层？',1,'3.1','员工拿一份内部流程，说可以不履行法定义务。你需要区分法律、行政法规、部门规章、自律规则与内部制度。','内部班规不能推翻国家法律；层级不同，适用对象也要核对。',[
['规范层级','法律、行政法规、部门规章、自律规则等构成基金规范体系。低层级制度不能突破上位法。','内部制度允许法令禁止的行为，该怎么处理？','遵守上位规范并纠正内部制度','内部制度永远优先','看谁声音大','按收益高低选择规则'],
['适用范围','规则适用要看主体、产品、行为、时间和地域等条件。','一条公募规则能无条件套到所有私募上吗？','不能，需要核对适用范围','能，基金没有区别','只有机构规模影响适用','广告写了就适用'],
['规则效力','正式发布、施行、修订、废止与征求意见是不同状态；征求意见稿不能当作现行最终规则。','看到征求意见稿中的新门槛，最稳妥的做法是？','核对是否正式发布和施行','立刻当作生效规定','认为永远不会变化','只看文件标题'],
['定位义务','分析法规题应先识别谁在做什么、依据哪类规范，再判断义务与责任。','分析违规情境时，应先做什么？','识别主体、行为与适用规范','猜题目最长选项','只看结果是否赚钱','只看管理人是否有名']]);
unit('监管与自律，谁负责什么？',1,'3.2,3.3','同一机构可能面对证监会的行政监管、协会的自律管理和交易场所规则。制度并非互相替代。','像道路上同时有交通法律、行业规范和具体停车场规则，各有权限。',[
['监管目标','基金监管关注投资者保护、市场秩序与风险防范等目标，不承担收益保证职能。','监管机构对基金进行监管意味着什么？','履行监管职责，不保证收益','为基金本金兜底','替投资者选择所有产品','代替基金管理人经营'],
['监管分工','证监会与相关金融管理部门依据职责监管；跨境与货币等事项要核对人民银行、外汇管理部门的职责。','遇到外汇相关业务，要怎样理解监管关系？','按具体事项核对相关部门职责','协会可以代替所有行政部门','只听销售人员解释','无需考虑跨境规则'],
['行业协会','基金业协会属于行业自律组织，依法依规实施登记备案、自律管理等职责，行政处罚与自律处分应区分。','协会自律处分与行政处罚应怎样理解？','性质和实施主体不同','完全相同','自律可废除法律','行政机关不参与监管'],
['交易场所','交易场所依据其规则对交易参与者和市场活动实施相关自律管理。','在交易场所开展业务时，哪种理解正确？','还需遵守适用的交易场所规则','只需服从管理人内部制度','收益好可忽略规则','交易场所保证成交价']]);
unit('公募管理人为何有准入与治理要求？',1,'4.1','公众把钱交给一个机构，不只是看投资经理的能力，还要看机构资格、治理、持续经营与退出安排。','飞机能起飞，需要机长、维护、调度和安全制度共同工作。',[
['准入与职责','公募管理人须符合适用准入要求，并履行管理基金财产、投资决策、核算披露等法定职责。','评价管理人能否合法开展业务，首先应核对？','适用准入资格与业务范围','过去一年广告数量','办公装修颜色','员工社交热度'],
['治理与经营','治理应形成决策、执行、监督与制衡，不能依赖某个人口头承诺；国际化业务还有相应制度要求。','把所有关键权力集中给一人，会增加什么问题？','缺少制衡与利益冲突风险','天然提升合规水平','自动满足跨境规则','取消监督需要'],
['风险准备与财务','风险准备金制度和财务指标是管理人的制度约束，具体计提口径与要求需核对现行原文。','风险准备金制度意味着基金一定不亏吗？','不意味着，它是相关风险管理制度','意味着完全保本','可以替代投资限制','只影响基金名称'],
['职责终止','管理人退出或职责终止需要法定程序及资产、文件与业务交接，不能把基金财产据为己有。','管理人职责终止时，首先需要关注什么？','程序、交接与投资者权益保护','立即把资产转入个人账户','删除全部业务资料','停止所有信息提供']]);
unit('私募管理人：登记不是信用背书',1,'4.2','一家机构展示登记编号，宣称投资保本。编号回答的是登记信息，不能证明其产品一定盈利。','有营业执照不等于餐厅每一道菜都符合你的需求。',[
['登记与退出','私募管理人登记、撤销与注销属于不同状态，需要依据适用条件和程序判断。','查询到私募管理人登记信息，能推出什么？','需要进一步核查产品与风险，不能推出保本','全部产品得到官方担保','机构永不退出','销售给任何人都合法'],
['法定职责','依法依约管理基金财产、为投资者利益履职，不能侵占挪用基金财产。','管理人临时把基金资金用于自己的公司周转，判断重点是？','是否违反财产独立与管理职责','只要未来归还就无需判断','是否使用蓝色银行账户','资金在账外就不受约束'],
['专业经营','管理人需满足适用的经营、人员和专业要求，不能靠登记编号替代实际履职。','登记编号能替代专业经营能力吗？','不能，登记与持续履职应分别看','能，登记后无其他义务','只有募资时才需人员','产品越多越无需风控'],
['内部治理','私募管理人也需要决策、执行、监督与利益冲突管理等治理安排。','私募规模小，可以不管利益冲突吗？','不可以，应履行适用治理与冲突管理义务','可以，私募没有治理义务','只需投资者不投诉','只需销售额达标']]);
unit('托管人和服务机构的边界',1,'4.3,4.4','基金管理人、托管人、销售、估值和法律服务机构都出现了。要区分哪些职责可以委托，哪些责任不能凭委托免除。','一场演出有导演、财务和舞台团队，分工不意味着导演无需负责。',[
['托管职责','托管人依法依约保管财产、办理资金清算等并履行相应监督职责，具体范围应结合适用规则。','托管人与管理人职责的核心区别是？','资产保管等与投资管理的分工','托管人必定选择收益最高的股票','管理人无需承担责任','托管人就是投资者'],
['准入要求','不同服务业务有相应资质与业务规范，不能仅凭服务合同替代准入资格。','选择基金销售服务机构，首先应核对什么？','适用业务资格与规范','网站背景色','是否有明星代言','联系电话位数'],
['委托与责任','外包部分服务并不当然免除管理人依法应承担的责任；应审慎选择、监督服务方。','管理人说已外包核算，因此自己不承担任何责任，应怎样理解？','委托不当然免除法定责任','外包可移转所有法定义务','服务方可改写法律','无需核查服务质量'],
['托管终止','托管人职责终止与更换需要遵循相应程序与交接安排，不能让基金资产无人管理。','更换托管人时，需要关注什么？','法定程序、资产与文件交接','只换宣传名字','销毁持有人记录','由销售个人保管基金财产']]);
unit('从业人员与长效考核',1,'4.5','基金经理只关心当季规模，可能忽视投资者长期利益。人员管理和长效考核就是把行为与责任连接起来。','只奖励短期分数，容易让人忽视真正的学习；考核也需要长期视角。',[
['人员管理','任职、离职与资格管理须遵循适用要求；考试通过与机构办理从业资格注册不是同一环节。','通过两科考试后，是否等于所有岗位都自动完成注册？','不等于，还需满足相应岗位与注册要求','等于，任何岗位都自动合规','不再需要任何后续管理','等于获得收益担保资格'],
['执业规范','人员应在职责权限内专业审慎执业，遵守业务规范和利益冲突管理要求。','员工发现操作超出自身授权时，合适做法是？','按权限与程序报告或取得合法授权','先做完再隐藏','只要客户口头同意就无须程序','收益高即可越权'],
['长效考核','2026绩效考核管理指引强调长效激励约束与持有人利益绑定，应核对适用主体和指标原文。','绩效评价为何不能只看短期规模？','会忽视长期业绩、风险和持有人利益','短期规模等于全部客户利益','风险无需参与考核','长期业绩无法被观察'],
['适用与更新','公募人员考核规则不能无条件套用所有机构；新版规则还需核对施行与旧规废止情况。','读取绩效指引时应同时核对什么？','适用主体、施行状态与具体指标','只核对标题字体','只核对机构地址','只凭上一版笔记']]);
unit('廉洁从业：为什么礼物也会成为风险？',1,'4.6','供应商以赠礼换取合作，客户以利益要求特殊待遇。要识别利益输送，而非只看礼物价值或对方关系。','裁判收下参赛者好处，会伤害比赛的公平。',[
['廉洁要求','不得通过不正当利益影响业务决定，机构需建立制度、教育、监督和报告等安排。','供应商赠礼要求优先采购，主要风险是什么？','不正当利益与业务决定绑定','礼物包装不专业','供应商数量不足','采购文件太长'],
['机构责任','廉洁从业不只是员工个人责任，机构还需承担管理与相关报告责任。','机构发现疑似利益输送，应怎样处理？','依规调查、处置并履行适用报告责任','只让员工私下道歉','只要未曝光就不用管','只追求保住销售额'],
['纪律规范','党内廉洁自律、纪律与问责规范有特定适用对象，应区分党纪、行政责任和刑事责任。','判断党内纪律要求时，先应确认什么？','适用对象与具体行为规范','所有客户是否盈利','基金收益排名','员工住所面积'],
['犯罪构成','贪污贿赂类罪名需要依主体身份、职务关联、行为和构成要件区分，金额与适用解释应查原文。','给一项行为定具体罪名，不能省略哪一步？','分析主体、行为和法定构成要件','比较宣传口号','查看基金名称','只判断是否给过礼物']]);
unit('公募募集与产品：权利从哪里来？',1,'5.1','你认购一只新基金，需要了解合同、募集安排、份额权益和产品风险。募集期交易与基金存续期申赎不同。','加入一个共同项目前，先看协议和成立条件。',[
['产品约定','产品类型、合同和运作方式共同限定基金的权利义务，不能由销售人员任意改写。','销售口头说基金与合同不同，应优先怎样做？','核对正式文件及适用规则，澄清差异','完全依赖口头保证','只看礼品价值','忽略合同风险'],
['认购与申购','认购通常对应募集期购买，申购对应基金成立后按运作安排购买。','投资者在基金募集期购买份额，通常称为？','认购','赎回','基金清算','二级市场卖出'],
['募集成立','募集、合同生效与后续运作有不同环节和条件，具体规模、人数与期限要查现行条文。','基金开始募集是否意味着合同已当然生效？','不当然，还要看成立与生效条件','是，所有条件自动满足','是，托管人会垫资','是，销售方可免除条件'],
['权益风险','持有基金份额意味着享有相应权益并承担风险，销售文件不能保证收益。','关于份额持有人权益，哪项正确？','依法依约享有权益，同时承担投资风险','只享收益不承担风险','都享固定利息','可以任意提取基金所有资产']]);
unit('份额交易、申购与赎回',1,'5.1','今天提交赎回与今天到账不是同一件事；场内交易价也不必等于基金净值。','下单、成交、结算和收款，是不同节点。',[
['净值与价格','基金净值与场内交易价格是不同概念，溢价或折价需结合供求及具体机制分析。','场内价格高于净值时，怎样理解？','可能存在溢价，二者不必相等','净值已必然按价格改写','属于固定利息增加','意味着基金保本'],
['申请与确认','申赎有申请、确认和款项支付等步骤；交易日、时间与适用净值要看产品规则。','提交赎回申请后，就必定立即收到现金吗？','不必然，还需确认与支付流程','必定，申请等于到账','管理人必须个人垫付','托管人必须当天保本'],
['流动性管理','赎回压力与资产流动性之间可能错配，需要相应制度和风险管理。','投资资产难以快速出售但投资者集中赎回，突出问题是什么？','流动性风险','基金名称风险','汇报格式风险','自然消失的风险'],
['投资交易约束','基金投资交易须遵守合同、适用范围、比例与利益冲突限制，不能只追求短期回报。','一项交易高收益但违反投资限制，应怎样处理？','不得以收益为理由突破限制','收益高就可例外','只要销售同意就能做','不用核对合同']]);
unit('销售与适当性：从匹配开始',1,'5.1','客户要在下个月付学费，却被推荐长期高风险产品。销售不能只询问收益目标。','给不同能力的人安排不同难度训练，先了解人，也要了解课程。',[
['了解双方','适当性需要了解投资者情况与产品特征，在风险、目标和期限等方面匹配。','一个月后必需使用的生活资金，应优先关注什么？','资金需求、期限与风险承受能力','最高历史收益率','销售人员奖金','产品包装颜色'],
['销售规范','销售行为需遵守适用业务规范，不能以误导、欺诈或不当利益吸引投资者。','销售将过去收益说成未来保证，问题在哪？','把历史表现误导为未来承诺','历史表现永远无用','只要客户开心就合规','只有收益下降才违规'],
['风险告知','风险告知应真实准确且让投资者理解，签名不应成为忽略实质履责的理由。','客户签署文件，但未得到真实风险说明，签名能当然免除责任吗？','不能，仍要看是否实质履责','能，任何责任都消失','能，签名等于盈利','能，合同等于兜底'],
['宣传推介','宣传推介需核对内容、渠道、业绩展示与风险提示等要求，不能选择性误导。','仅展示盈利月份隐藏亏损月份，容易导致什么？','片面业绩展示与误导','改善知情判断','消除市场风险','满足全部披露义务']]);
unit('公募披露与清算',1,'5.1','基金不再继续运作，需要说明发生了什么、如何处理资产和持有人权益。宣传材料不能代替应披露的报告。','结束共同项目也需要盘点、报告和结算，不只是关掉门。',[
['信息披露','披露应依法依规进行，真实、准确、完整并满足相应及时性要求。','管理人只告诉投资者盈利消息，是否足够？','不足，需遵守完整真实的披露义务','足够，亏损是秘密','只需给大客户报告','只需社交平台更新'],
['报告角色','定期报告、重大事项等信息与宣传推介用途不同，应区分适用披露形式与节点。','广告能当然替代依法应披露的报告吗？','不能，用途与规范不同','能，只要设计精美','能，只要点击量够高','能，只要无投诉'],
['终止原因','终止应依据法定或约定情形，不能由销售个人任意决定，程序需核对规则。','基金销售人员可直接宣布基金终止吗？','不能任意决定，应依据相应条件和程序','可以，销售掌握所有权力','可以，只要客户人数少','可以，资产无需交接'],
['清算分配','清算需要处理财产、债权债务、费用和分配等事项，剩余财产分配须依法依约。','清算时如何对待基金债务与资产分配？','依法依约处理债务、费用与剩余财产分配','先将全部资产给管理人','仅按客户联系频率分配','不需要披露处理情况']]);
unit('私募资管计划，不要与私募基金混用规则',1,'5.2','证券机构设立的私募资产管理计划，与私募基金管理人管理的基金，名称接近但制度不同。','两种交通工具都载客，但驾驶资格与行驶规则可能不同。',[
['主体与产品','私募资产管理计划与私募基金应从管理主体、产品性质及适用规则区分。','看到“私募”二字，能把所有制度直接混用吗？','不能，应确认具体主体与产品','能，名称相同就是同一制度','只看收益率即可','只看宣传材料页数'],
['募集与备案','募集和备案按相应规则实施，备案不等于对收益或投资价值的保证。','资管计划备案能证明必定盈利吗？','不能，备案不等于收益保证','能，备案机构承担亏损','能，备案即保本','能，风险披露不再需要'],
['运作与风险','类别、分级、投资范围与限制、关联交易等有适用要求，应逐项核对。','进行关联交易时，为什么要额外检查？','可能涉及利益冲突及适用程序','因为关联交易必定盈利','只需对方口头批准','关联关系免除程序'],
['变更终止','变更、终止、清算与披露均有相应要求，不能只处理资金而忽略程序。','计划终止时，哪种处理更符合规范？','按规则履行清算、披露与相关程序','静默关闭账户','由员工自行分配全部财产','只撤下宣传网页']]);
unit('私募基金从募集到清算的规范',1,'5.3','投资者认购私募产品后，仍需持续获取估值、费用、运作和重大事项等信息。','买票只是旅程开始，旅途中还要有路线、通知和结束安排。',[
['募集与备案','私募募集须符合适用对象与方式要求，管理人登记和产品备案应分别看。','机构已登记，能推断某只基金也已备案吗？','不能，机构登记与产品备案不同','能，所有产品自动备案','能，无须查看产品信息','能，登记就是资产保险'],
['投资交易','基金投资交易应在法令与合同约束内进行，基金财产应独立，不可侵占挪用。','基金资金可按管理人需要任意混同吗？','不可以，应遵守财产独立等要求','可以，只要一起核算','可以，私募资金属于管理人','可以，收益正就免除责任'],
['费用与估值','费用收取和估值应遵守适用制度及合同约定，避免任意收费或不合理估值。','管理人临时新增合同没有依据的费用，应怎样判断？','核对合同、规则与合法程序','只要管理人需要就合理','投资者无权知悉费用','费用越多投资越安全'],
['持续义务','申赎登记、披露报送、终止清算等都是持续运作的组成，不能只重募集。','私募基金完成募集后是否仍有信息义务？','有，应按适用规则持续履责','没有，合同已签完','只向投资经理披露','只在基金盈利时披露']]);
unit('反洗钱：先识别人和资金',1,'5.4','有人要求用他人身份开户或拆分可疑交易。识别客户和交易异常，比只填一张表更重要。','机场核验身份不仅看票，还要确认乘客与证件相符。',[
['义务目的','反洗钱通过客户尽职调查、记录保存、监测与报告等措施识别和防范相关风险。','反洗钱流程的主要目标是？','识别与防范资金被用于洗钱等风险','保证所有投资盈利','减少所有交易费用','提高广告转化率'],
['客户识别','了解客户及依法需要识别的受益所有人等信息，不应以他人名义规避核验。','客户要求借用他人身份开户，合适做法是？','依规核验并处理异常要求','直接配合以方便成交','只要金额小就忽略','把身份资料删除'],
['监测报告','大额与可疑交易报告有相应规则，不能只凭金额小便排除可疑性。','连续小额交易呈明显异常模式，应该怎样看？','结合交易模式和规则识别可疑性','金额小就永不可能可疑','只能按广告理解','无需保存任何记录'],
['记录与保密','资料保存、报告与保密应按法定要求进行；不应向客户泄露不应披露的报告信息。','员工可随意把内部可疑报告发给客户吗？','不可以，应遵守保密与报告要求','可以，客户提出就必须给','可以，报告没有用途','可以，销售业绩优先']]);
unit('合规：每个部门都要负责',1,'6.1','业务团队说合规是合规部门的事。实际上，治理层、管理层、业务部门与合规职能有不同职责。','消防员重要，但每个人都不能随意堵塞逃生通道。',[
['共同责任','合规管理覆盖机构经营全过程，业务部门不能把自身履责义务完全推给合规部门。','业务部门能把全部合规责任转给合规负责人吗？','不能，各主体应承担自身职责','能，设了合规岗就无责任','能，只要签一份文件','能，只要利润达标'],
['组织职责','董事会等治理主体、管理层、合规负责人和部门等承担相应职责，需形成制度保障。','合规职责设计首先要做到什么？','明确各主体职责与有效保障','所有权力口头集中','只依靠业务人员自觉','仅制作一张宣传图'],
['机制保障','独立性、专业资源、考核与报告等保障机制支持合规职能有效履行。','如果合规人员因提出风险而受不当打压，会伤害什么？','合规独立履职及制度有效性','基金名称辨识度','客户数量统计','网页加载速度'],
['管理活动','制度审查、监测检查、培训咨询与整改等是合规管理常见活动，不只是事后盖章。','合规管理只在出事后签字是否充分？','不充分，应贯穿业务及整改','充分，过程不需检查','充分，只需保存印章','充分，只要没有投诉']]);
unit('风险：识别、评估、应对、监测',1,'6.2','基金账面赚钱，却无法及时应付赎回；另一笔交易因系统错误失败。风险并不只有股价下跌。','做旅行计划，既看天气，也看交通、预算和应急安排。',[
['风险分类','市场、信用、流动性、操作等风险有不同来源，管理措施应对应风险类型。','资产难以出售导致赎回支付压力，主要是？','流动性风险','单纯广告风险','基金命名风险','必然已实现收益'],
['信用风险','交易对手或债务人不能履约可能导致信用损失，不同于一般市场价格波动。','债务人不能按约偿付，突出风险是什么？','信用风险','品牌颜色风险','必然的流动性改善','收益保证'],
['管理环节','识别、评估、应对与持续监测形成闭环，风险偏好与限额需有对应制度。','识别出风险后，为什么不能就此停止？','还需评估、应对并持续监测','识别等于风险消失','只需记录名称','收益高可取消措施'],
['组织职责','风险管理需要明确治理、管理、业务与风险职能的职责，不能只靠一个模型。','一个模型输出低风险，是否足以取消组织管理？','不足，应结合组织职责与制度措施','足够，模型承担所有责任','足够，管理人无需判断','足够，数据无需核验']]);
unit('内控：为什么流程需要制衡？',1,'6.3','同一人下单、付款、核对账目，错误很难被发现。内控让重要环节能被独立核对。','出卷、阅卷与复核由不同角色承担，能降低盲点。',[
['内控目标','内控支持合规经营、资产安全、信息可靠与有效运作，不保证不存在任何风险。','内部控制是否能保证永不出错？','不能，但能降低与发现相关风险','能，所有风险归零','能，市场不会变化','能，客户一定盈利'],
['要素联系','控制环境、风险评估、控制活动、信息沟通与监督等要素相互配合。','只写制度但不监督执行，问题是？','控制体系缺少有效监督与落实','制度越厚越有效','监督没有必要','信息沟通可代替全部控制'],
['不相容职责','重要业务中的不相容职责应适当分离，独立核对降低错误与舞弊机会。','同一员工发起和独立复核自己的付款，有何问题？','缺少职责分离和独立核对','自然提高监督独立性','完全免除操作风险','不需要任何记录'],
['制度层次','内部控制制度有不同层次，纲领、基本制度与业务规则应衔接；具体结构查教材原文。','上层制度与具体业务流程应如何衔接？','原则落实到可执行的业务规则','具体流程可任意违背原则','只有原则无需落实','仅保留文件封面']]);
unit('职业道德与专业审慎',1,'7.1,7.2,7.4','一项操作似乎找不到明确禁止条文，却可能损害客户。职业道德帮助判断边界，专业审慎要求有能力与证据。','好医生既守规章，也不凭未经验证的猜测给患者处理。',[
['道德与法律','职业道德与法律规范共同约束行为，不能用“未明确禁止”否定所有道德要求。','没有找到直接禁止条文，就一定符合职业道德吗？','不一定，还需考察职业责任与客户利益','一定，所有道德要求自动消失','一定，只看盈利','一定，只看行业惯例'],
['守法合规','理解并遵守适用规则，不能以客户要求、领导指示或收益目标为违法免责依据。','领导要求绕开明确规则，员工应怎样做？','遵守规则并按程序处理','领导指示永远优先','只要口头要求就免责','先做再删除证据'],
['专业能力','专业审慎要求具备必要专业能力并持续更新，不应超能力提供无根据判断。','不了解一项复杂产品却给出确定建议，主要缺陷是？','专业能力与审慎判断不足','建议字数太短','客户名气不够','投资期限太长'],
['充分依据','专业判断应基于合理调查与充分依据，不能以未经验证传言替代分析。','形成投资判断时，哪项更符合审慎要求？','验证资料并形成合理分析依据','只看社交平台传言','只复制别人的结论','只选高收益广告']]);
unit('诚实守信与交易红线',1,'7.3','员工获得尚未公开的信息，用亲友账户交易；又有人想通过交易制造虚假的供求。获利不改变行为性质。','考试不能提前偷看答案，也不能把伪造分数给别人看。',[
['未公开信息','内幕交易与利用未公开信息交易应按信息性质、主体与行为区分，不能借他人账户规避。','用亲友账户利用禁止使用的未公开信息交易，能规避约束吗？','不能，应按实际信息与行为判断','能，账户不在本人名下','能，只要盈利','能，只要不公开发帖'],
['市场操纵','通过不当交易等影响市场价格或交易量，可能违反市场秩序要求，应依据具体构成判断。','制造虚假交易量以诱导他人，核心风险是什么？','市场操纵与误导市场','提高真实价格发现效率','合法保证收益','仅属于排版错误'],
['客户欺诈','虚假陈述、隐瞒重要信息等可能损害客户知情判断，盈利结果不能自动消除行为问题。','投资后来赚钱，能否当然证明前面的虚假宣传合规？','不能，行为本身仍需判断','能，结果好就没有责任','能，客户获利等于豁免','能，广告可任意承诺'],
['公平竞争','不正当竞争有相应禁止行为与法律责任，竞争应以合法方式进行。','为了获客散布对手虚假信息，符合诚实守信吗？','不符合，应按规则判断相关责任','符合，抢到客户即可','符合，行业竞争无需法律','符合，只要没有交易']]);
unit('客户至上、忠诚尽责与保密',1,'7.5,7.6,7.7','客户利益与机构短期收入冲突，员工又掌握客户资料。要同时判断责任、利益冲突与保密边界。','受托替人保管东西，不能拿去满足自己的需求，也不能随便公开。',[
['客户利益','客户至上要求在适用职责范围内优先考虑客户合法利益，不能承诺违反法律的要求。','客户要求违规操作，客户至上意味着？','不能违规，应在合法职责内保护其利益','必须无条件满足','可以隐藏交易','可以绕开所有限制'],
['忠诚尽责','忠诚尽责要求履行受托职责、防范冲突，不侵占不挪用，不能只重个人获利。','员工将合适机会优先留给自己，判断应关注什么？','利益冲突和受托职责','员工个人喜好','机会出现时间','广告排名'],
['保守秘密','客户和机构的非公开信息应依规保密；依法需报告或披露的情况要区分。','员工能把客户投资信息用作公开营销案例吗？','需要符合保密、授权与适用要求','只要换个字体就能公开','客户投资赚钱就可公开','信息在内部表格就可转卖'],
['公平对待','在相应义务范围内公平对待客户，不能因个人关系进行不当利益输送。','给亲友客户不当优先利益，会引出什么问题？','公平对待及利益冲突问题','提升所有客户公平','自然满足忠诚尽责','可以替代信息披露']]);
unit('行业文化为何影响业务行为？',1,'8.1,8.2','机构口号写着长期投资，考核却只看短期销售。文化要体现在决策、激励和对客户的行为中。','学习文化不能只写在墙上，还要看每天怎么教、怎么反馈。',[
['文化与行为','行业文化通过共同价值观与行为实践影响机构和人员的业务选择。','判断文化是否落实，更应看什么？','制度和实际行为是否一致','墙面标语数量','办公楼高度','广告发布时间'],
['诚信底线','中国特色金融文化强调诚实守信、不逾越底线。','为了销售夸大收益，主要违背哪种文化要求？','诚实守信与底线意识','降低业务学习成本','优化品牌色彩','拓展办公面积'],
['利益与风险','以义取利、稳健审慎要求合法合理经营并重视风险，不可为利益突破约束。','将高收益目标置于风险和规范之上，有何问题？','忽视义利关系与稳健审慎','天然体现责任','自动改善投资者保护','可以取消所有风控'],
['长期与规范','守正创新和依法合规要求创新遵守基本规范，避免脱实向虚和以创新名义违规。','推出新产品就能不受已有规范约束吗？','不能，应依法合规开展创新','能，创新可以豁免全部规则','能，只要名称新颖','能，只要市场欢迎']]);
unit('2026新增规范与诚信管理',1,'8.3,8.4','复习材料还停留在旧大纲，漏掉纪律、问责和诚信管理。你需要识别规范适用对象并按新版目录核对。','导航更新后，旧路线可能遗漏新路口。先确认版本，再进入细节。',[
['版本核对','2026大纲列明八项规定及实施细则、纪律处分、问责等要求，学习应核对对应原文和适用对象。','旧笔记没有新版规范，该怎样处理？','对照2026大纲与原文补齐','默认旧资料完整','删掉新版要求','只增加题量'],
['作风与制度','作风建设相关规范强调相应纪律与工作要求，不能用形式主义替代实际履责。','只填报告而未实际履行要求，反映什么问题？','形式与实质履责脱节','文件多就合规','无需关注工作实效','客户不知情就无风险'],
['纪律与问责','纪律处分与问责需按规范的对象、程序、情形与措施理解，不能把所有责任混为一种。','党纪处分、行政处罚、刑事责任之间应如何看？','分别依据适用规范判断','完全相同','只按利润决定','均由销售人员决定'],
['诚信管理','社会信用与证券基金期货行业诚信管理有相应记录、监督与使用规则。','诚信记录管理的意义是？','支持信用监督与规范执业','替投资者保证收益','取消所有准入条件','代替基金核算']]);
unit('股权基金：先看完整的一笔生意',3,'1.1,1.2,1.3,1.4,1.5','投资者把钱交给基金，基金投企业、参与管理，最后争取退出。各环节都有权利、责任与风险。','像建设一个长期项目：筹资源、选择项目、持续管理、收回资金。',[
['长期权益','股权基金主要投资企业权益，投资与退出时间较长、流动性受限、收益不确定。','为何不能把股权基金当作随时可取的存款？','投资期限与退出约束不同','每月都支付固定利息','资金由银行无条件保证','基金登记可消除风险'],
['运作架构','投资者、基金、管理人及服务机构形成运作架构；募集、投资、管理、退出是连续过程。','分析一个基金，为什么要看募投管退全链条？','各阶段影响最终回报及风险','只看募集规模即可','退出与回报无关','投后可以省略'],
['权利义务','管理人、投资者与服务机构的权利义务各有边界，合同和规则共同约束。','投资者与管理人权利义务依据什么判断？','合同与适用规范','管理人社交影响力','基金名字长度','客户是否认识销售'],
['发展与作用','股权基金支持企业融资、创新和资源配置；国内外发展脉络、现状与政策应按官方资料更新。','判断基金对经济的作用，合理关注点是？','融资支持、创新与资源配置','是否能保证每个项目成功','是否代替所有企业经营','是否取消风险承担']]);
unit('管理人要具备什么条件？',3,'2.1','机构有资本不等于具备专业管理能力。登记经营、出资人和实际控制人、从业人员与履职都有要求。','有一辆车，不等于有运营运输服务的资格与能力。',[
['经营要求','私募管理人有基本经营和专业化要求，须具备真实持续经营与相应人员制度。','只有空壳公司和登记编号，能替代持续经营要求吗？','不能，还要持续满足适用要求','能，登记后无需员工','能，只要外包所有职责','能，机构有地址即可'],
['控制主体','股东、合伙人与实际控制人的合规要求，是防范风险与利益冲突的一部分。','核对管理人时，为什么要了解实际控制人？','识别控制关系及适用合规风险','只为选择基金名称','只为比较年龄','控制关系永不影响业务'],
['人员要求','从业人员需符合相应任职、专业与执业要求，岗位职责应明确。','管理人可以靠一名销售完成所有专业职责吗？','不能用销售岗位替代所有专业履职','可以，募到钱就具备全部能力','可以，合同能自动投资','可以，登记机构代为履职'],
['管理职责','依法依约为基金履行管理职责，不能把基金财产作为机构自有财产。','管理人可将基金财产自由用于机构支出吗？','不可以，应依法依约并保持财产独立','可以，基金资金属于管理人','可以，记在日记即可','可以，只要以后募新资金']]);
unit('信义义务与专业治理',3,'2.2,2.3,2.4','管理人知道的信息更多，也掌握决策权。受托关系要求其不能利用这种优势损害投资者。','替朋友买东西，要替朋友考虑，也要认真核对，不能私收回扣。',[
['忠实义务','信义义务强调受托角色的忠实与审慎，需防范利益冲突和利益输送。','将好项目不当留给自己、风险留给基金，问题是？','违背受托利益与冲突管理要求','只是项目分类','提高所有投资者利益','属于正常信息披露'],
['专业审慎','管理人应以必要专业能力与合理调查形成决策，不是保证判断永远正确。','一次投资亏损，是否自动等于违反信义义务？','不能自动认定，应看决策与履职过程','任何亏损都构成违约','只要盈利就一定合规','亏损只看广告承诺'],
['制度保障','专业化需人员、流程与制度支持，而非只依赖个别明星人员。','专业化的制度保障应重点看什么？','团队、流程和持续履职机制','明星代言数量','办公室风格','机构简称'],
['内部治理','治理结构、决策、激励与监督机制应适配组织形式，形成制衡。','管理人治理为什么需要监督机制？','检查权力行使、防范冲突与失职','保证每个项目盈利','替代所有尽调','取消岗位职责']]);
unit('公司型、合伙型与契约型基金',3,'3.1,3.2','同样集合资金，组织形式不同会影响治理、责任承担和税务处理。GP、LP不能与管理人、投资者概念简单画等号。','同一个项目可用公司、合伙或合同安排组织，规则随组织形式改变。',[
['组织形式','公司型、合伙型与契约型的法律基础、治理和权利结构不同。','选择基金组织形式，影响哪些方面？','治理、责任与税务等安排','只影响宣传标题','必定决定收益高低','完全不影响合同'],
['普通合伙人','普通合伙人原则上对合伙企业债务承担无限连带责任，有限合伙人与其责任机制不同。','GP与LP的责任机制是否相同？','不相同，要区分普通与有限合伙人','完全相同','GP只按广告金额负责','LP永远无需出资'],
['有限合伙人','有限合伙人一般以认缴出资额为限承担责任，执行事务等规则需核对法律与合伙协议。','有限合伙人责任的一般边界是什么？','以认缴出资额为限，具体看适用规则','所有个人财产自动保证基金盈利','可不履行出资约定','与基金合同完全无关'],
['契约与分类','契约型以合同安排权利义务；组织形式与投资阶段、方式等分类维度不同。','契约型与创业投资基金能同时描述某基金吗？','能，组织形式与投资类型是不同维度','不能，标签只能有一个','契约型只能买国债','创业基金必定公司型']]);
unit('创投与并购：投资什么阶段？',3,'3.3','早期企业可能还没稳定收入；并购标的通常已有业务。两类投资的判断、管理与退出重点不同。','培育幼苗与接手成熟果园，工作的重点不同。',[
['创业投资','创投通常支持创业与成长企业，需关注技术、团队、商业模式与成长风险。','面对尚未盈利的创业企业，尽调重点可包括？','团队、技术、商业模式与成长风险','只看当前固定利息','只比较物业面积','只要创始人承诺保本'],
['并购投资','并购投资关注取得相应权益与整合机会，控制、协同与整合风险重要。','并购完成后，为什么还要关注整合？','协同实现与运营文化整合会影响价值','签约后风险全部消失','协同效应必定立即实现','投后只适用于创投'],
['风险区别','投资阶段与控制方式不同，风险来源和价值创造方式不同；不能只比预期倍数。','比较创投与并购，合理做法是？','结合阶段、控制与风险来源分析','只看宣传回报倍数','认定并购无风险','认定创投必定失败'],
['政策核对','创投鼓励与优惠政策有适用条件和期限，不能把政策支持理解为投资保证。','有创投鼓励政策就意味着投资保本吗？','不意味着，还需核对条件与风险','意味着政府兜底全部损失','意味着免除所有税务','意味着任何投资均享优惠']]);
unit('母基金与S基金：买的是哪一层？',3,'3.4','母基金投资其他基金；S基金可通过二手份额等交易进入既有资产。要看底层资产、费用层级和剩余期限。','直接种树、投资果园经营者、接手别人持有的果园权益，是不同路径。',[
['母基金','股权母基金主要投资基金，可通过组合与管理人选择配置风险，但也存在多层费用与底层风险。','母基金主要配置的对象是什么？','其他基金等相关权益','只配置个人信用卡','必定只买上市股票','只能持有银行现金'],
['费用与风险','分散配置不消除风险，多层管理可能增加费用和信息穿透难度。','母基金分散投资后是否风险归零？','不归零，仍有底层风险与成本','归零，分散等于保本','归零，多层收费可抵消损失','归零，不需要尽调'],
['S基金','S基金关注私募股权二级交易，如受让存续基金份额或相关资产权益，需评估存量组合。','S基金购买存续基金份额，首要分析对象包括？','底层资产、剩余期限与交易条件','基金首字母颜色','卖方宣传视频时长','只看原始认缴金额'],
['二手不等于无风险','存量信息可能更多，投资期可能缩短，但定价、流动性、法律和底层资产风险仍存在。','二手份额交易必然比所有新基金风险低吗？','不必然，需分析资产和条件','必然，二手没有风险','必然，卖方保证价值','必然，折价就是利润']]);
unit('政府投资基金的目标与约束',3,'3.5','政府基金既涉及政策目标，也需要规范市场化运作。不能把政府背景当作收益承诺。','公共项目有公共目标，也需专业执行、预算与绩效管理。',[
['政策目标','政府投资基金通过市场化方式等支持相应政策目标，具体目标与范围以制度文件为准。','判断政府基金时，应同时考虑什么？','政策目标、运作原则与制度约束','只看政府名称','只看历史收益','只看投资者关系'],
['市场化机制','政府背景不排除专业管理、风险控制和相应市场化运作要求。','政府背景能替代投资分析吗？','不能，仍需专业分析与风险管理','能，政府背景保证所有项目成功','能，所有估值都不需要','能，合同可省略'],
['运作方式','出资、投资与管理安排须符合适用政策和规则，不可任意改变资金用途。','政府基金资金能随意偏离规定用途吗？','不能，要符合适用目标与规范','能，只要管理人想法好','能，投资者人数少','能，名称含产业即可'],
['绩效管理','绩效管理应结合政策与投资等目标，不能仅看短期账面收益。','绩效评价为什么要考虑政策目标？','基金具有相应公共政策任务','只为制作宣传页','政策目标保证所有收益','短期利润是唯一指标']]);
unit('合格投资者与适当性',3,'4.2','一个人愿意承担风险，不代表自动满足合格投资者资格；财富门槛、风险能力和产品匹配需要分别检查。','能付学费，不一定具备某项专业课程的入学条件与基础。',[
['资格与匹配','合格投资者标准与适当性匹配是不同检查；满足资格不代表所有产品都适合。','达到财富门槛，能推出适合所有私募吗？','不能，还需产品与风险匹配','能，财富消除风险','能，无需了解期限','能，客户声明可替代全部程序'],
['标准的完整性','按大纲列示暂行办法，标准涉及相应风险识别与承担能力、单只金额和资产或收入等条件；须核对现行原文及例外。','核对合格投资者标准应怎样做？','把能力、金额及资产收入条件等完整核对','只看投资者自称合格','只看职业名称','只看是否认识管理人'],
['投资者分类','专业投资者和普通投资者按适用制度划分，不是按个人对金融的兴趣划分。','客户说自己爱看财经新闻，就一定是专业投资者吗？','不一定，应核对法定分类条件','一定，兴趣等于法定资格','一定，只要年满18岁','一定，只要愿意投资'],
['证明与实质审核','募集机构需履行实质审核等适用要求，不能非法拆分安排使不合格者参与。','把不合格者资金拼成一个合格金额即可合规吗？','不能用非法拆分或集合规避条件','可以，总额足够即可','可以，只需换个账户','可以，人数少于十人即可']]);
unit('募集与设立：程序为何不能跳？',3,'4.1,4.3','客户催促立即打款。募集流程中的特定对象识别、适当性、风险揭示、资格确认及合同安排各有目的。','先确认谁能参加，再介绍规则与风险，然后签订协议。',[
['非公开募集','募集方式要符合私募要求，不能向不特定公众任意宣传推介。','向不特定公众直播推介私募并承诺收益，有何问题？','可能违反非公开募集及推介要求','受众多就自动合规','只要点击量够高即可','直播能替代资格确认'],
['募集流程','流程环节保护私募性与知情决策，不能因投资者熟悉管理人而全部省略。','熟人客户是否可跳过所有募集程序？','不可以，应按适用流程履责','可以，关系好即可','可以，投资额大即可','可以，口头同意即可'],
['冷静期区分','冷静期与回访需结合基金类型、规则与合同，不能把私募证券基金的具体安排直接无条件套用股权基金。','复习冷静期题，先应确认什么？','基金类型、适用规则和合同安排','销售手机型号','基金规模排行榜','投资者是否开心'],
['设立与备案','设立和备案有相应条件与合规要点；备案不构成对投资价值的确认。','基金完成备案，是否表示投资价值获官方保证？','不表示，仍需独立判断风险','表示，基金必定盈利','表示，不需再披露','表示，任何人都可购买']]);
unit('基金合同：先把钱怎么走写清楚',3,'4.4','投资者认缴、实缴和分配都写在文件里，管理费、投资范围、治理与期限也影响最终权益。','共同开店前，把出资、分工、费用和散伙安排说清楚。',[
['出资安排','认缴承诺与实缴资金不同，缴付时间、违约责任等应在合同中明确。','认缴额等于已经到账的现金吗？','不等于，还要看实缴情况','等于，签字即到账','等于，管理人会自动补足','等于，资产估值可替代缴款'],
['费用条款','费用类别、计提基础、费率和支付方式共同影响成本，应看完整口径。','相同费率为什么成本仍可能不同？','计提基础、期间与其他条款不同','同费率成本必定相同','费用与合同无关','只有客户年龄决定成本'],
['投资与组织','投资范围、决策机制、内部组织、利益冲突与期限等条款需要协同理解。','合同中治理与投资范围有什么意义？','限定运作边界与决策安排','只是装饰文字','可由销售任意改写','仅在盈利时适用'],
['组织形式差异','公司章程、合伙协议与契约安排依组织形式不同，不能机械套用同一权利结构。','不同组织形式的合同可完全不作区别吗？','不能，应匹配各自法律与治理安排','能，只要文件页数相同','能，基金名字相同即可','能，出资人数相同即可']]);
unit('尽调：让证据推着判断走',3,'5.1,5.2','企业展示高收入。你还要问收入是否真实、能否持续、合同是否合法、现金是否回收。','看见漂亮房子，还要检查产权、结构和真实使用情况。',[
['一般流程','项目筛选、尽调、分析与决策、文件谈判和交割等环节相互关联，具体流程以制度安排为准。','尽调应服务于什么？','投资分析与决策，而非只完成报告','替代所有投资决策','保证退出价格','只改善路演设计'],
['业务尽调','业务尽调关注行业、产品、竞争、客户、商业模式与团队等。','分析客户是否依赖单一大客户，更接近哪项？','业务尽调','只属于基金税务','只属于托管报告','只属于清算分配'],
['财务与法律','财务尽调关注财务真实性、质量与现金流；法律尽调关注权属、合规、合同、诉讼等。','核查核心专利是否归公司所有，更接近哪项？','法律尽调','客户销售偏好调查','基金净值披露排版','基金份额交易'],
['验证方法','访谈、文件核验、交叉验证等提升证据质量；报告需呈现关键发现与风险。','仅复制企业宣传材料作为尽调报告，有何缺陷？','缺少独立核查与风险分析','信息越正面越可靠','宣传可替代全部验证','只要签名就证据充分']]);
unit('估值计算：从企业价值到股权价值',3,'5.3','企业有经营资产，也有债务。先分清估值对象，再选乘数或折现方法；数字是建立在口径和假设上的。','估一套带贷款的房子，房屋价值与房主最终拥有的净权益不同。',[
['企业与股权','简化例中，股权价值＝企业价值－净债务；净债务一般为债务减现金，需注意口径。','假设企业价值100、债务30、现金10，股权价值多少？','80','60','100','140'],
['市场乘数','市场乘数需要指标与估值口径一致；例如P/E通常对应股权价值，EV/EBITDA对应企业价值。','某企业净利润10，假设适用P/E为8，股权价值估计为？','80','18','1.25','800'],
['现金流折现','DCF将未来现金流按相应折现率折现，现金流口径与折现率必须匹配。','假设一年后现金流110、折现率10%，现值为？','100','121','110','10'],
['参数与场景','增长率、折现率、终值等假设影响结果；最近融资价要关注时间与条件变化。','最近融资后企业经营出现重大变化，可直接不作调整沿用价格吗？','不宜，需评估变化与可比条件','可以，历史价格永远不变','可以，融资价等于保本','可以，未来风险不重要']]);
unit('估值方法：为什么不能只用一个公式？',3,'5.3','成熟盈利企业与早期研发企业的信息不同。要根据阶段和资料选择估值方法，并检查假设敏感性。','尺子适合量长度，秤适合量重量；工具要匹配问题。',[
['成本法','成本法等从资产价值角度考虑，适用时需识别资产与负债及相关口径，不等同于市场成交保证。','成本法更主要从哪种角度看价值？','资产价值等角度','只从基金广告点击率','仅从人员年龄','只从企业名字'],
['风险资本法','风险资本估值逻辑可从预期退出价值按目标回报折回当前，并分析稀释等因素。','假设5年后退出价值320、目标年回报率100%，无其他调整，折回现值为？','10','64','160','320'],
['不同阶段','未盈利企业可能无法直接使用有意义的P/E，应综合其他指标、方法与假设。','净利润为负的早期企业，直接用正P/E机械估值的主要问题是？','指标与方法可能不适用','早期企业一定零价值','所有估值都应同价','亏损会保证未来盈利'],
['敏感性','估值应看多种合理场景，不应把模型结果当成无条件事实。','模型显示高估值，投资者应进一步看什么？','假设、参数与敏感性分析','只看数字是否漂亮','只看图表颜色','不需核对输入信息']]);
unit('交易条款：优先权不是同一件事',3,'5.4','投资者希望追加融资时保持权益，又想在股东出售权益时获得机会；两种优先权适用情境不同。','新发门票与别人转卖旧门票，是两种交易。',[
['增资与转让','增资通常向公司投入资金、取得新增权益；股权转让通常支付给出让股东。','投资者购买原股东持股，款项通常支付给谁？','出让股东','必定支付给所有员工','必定成为新增注册资本','只支付给托管人'],
['认购与购买','优先认购权通常关注新增融资；优先购买权通常关注既有股权转让。','公司新增融资，讨论保持投资比例更相关的是？','优先认购权','所有退出方式完全一样','优先购买等同固定利息','基金清算登记'],
['经济权益','优先分红、优先清算及其他经济条款需依文件具体约定理解，不能视为外部保本保证。','约定优先清算，是否等于任何时候都保本？','不等于，仍取决于资产及条款','等于，由政府保证','等于，企业无需资产','等于，所有风险消失'],
['治理与退出','董事席位、表决、保护性条款及退出安排影响权力与权益，需要审查法律效力与适用条件。','看到回购条款，为什么仍需风险分析？','效力、条件与履约能力等可能影响实现','合同文字保证任何回购成功','回购义务人永远有钱','回购可以免除所有监管']]);
unit('交易结构：钱从哪里来，权益到哪里去？',3,'5.5','同样投资一家企业，可以直接增资、受让股权或股债结合；跨境结构还涉及不同法域与合规。','物流路线不同，途经规则与成本也不同。',[
['结构安排','交易结构需分清投资主体、标的、资金流、权益取得与退出路径。','画交易结构图首先需要明确什么？','谁出资、钱到哪里、取得什么权益','字体大小','路演音乐','基金logo颜色'],
['直接交易','增资与受让存量股权的资金流和对公司资本结构的影响不同。','资金进入公司而非原股东，通常更接近？','增资','原股东之间的二手转让','纯粹分红','基金清算分配'],
['离岸结构','离岸结构涉及不同法域、外汇与跨境合规，不应只看税务或融资便利。','设计跨境结构时，哪项不能忽略？','相关法域、外汇与适用监管要求','只看企业简称','只看销售地点','广告传播速度'],
['股债结合','股债结合包含不同权利、收益与风险机制，应分别分析适用性与约束。','股债结合是否意味着风险自动消失？','不意味着，应分析不同权利与风险','意味着债权保证全部股权收益','意味着免除合同','意味着没有信用风险']]);
unit('投后管理：投完才是下一段开始',3,'6.1,6.2','投资之后企业出现人员流失与资金紧张。要有信息收集、决策、部门职责、预警与处理机制。','种树后要观察、浇水和处理病虫害，不只记录栽种日期。',[
['覆盖期间','投后管理覆盖投资后至退出等相关期间，关注监测、治理与价值支持。','签完投资合同后是否可以停止管理？','不应，仍需投后跟踪与履职','可以，退出自动发生','可以，企业自负风险就免除管理','可以，基金已经备案'],
['决策机制','重大事项处理应有权限、决策与记录安排，不能只依赖个人临时判断。','投后发现重大风险，合理做法是？','依机制评估、决策并跟踪处置','只删掉报告','只把问题交给客户','等退出后再说'],
['组织制度','投资、投后、风控等部门与人员职责应衔接，并有制度和考核激励支持。','部门都认为投后监测由别人负责，会导致什么？','职责空白与信息处理风险','提高监测效率','风险自然消失','不会影响基金'],
['主要风险','经营、财务、治理、合规与退出等风险点应持续关注。','企业账面利润增长但持续现金流紧张，投后应怎样做？','核查利润质量、现金流及相关风险','只看利润忽略现金','自动提高估值','无需报告']]);
unit('投后策略：不同项目，不同关注点',3,'6.3,6.4','创投企业需要资源支持，并购企业可能需要整合。不能用同一个模板忽略所有项目差异。','不同植物有不同养护方式，但都需要持续观察。',[
['分类管理','不同产品和项目阶段可采用不同投后策略与分类管理，重点应匹配风险及价值创造需求。','对所有企业完全套同一套投后重点，有什么缺陷？','可能忽略阶段与风险差异','必定最专业','能消除所有工作量','能保证相同收益'],
['获取信息','报告、沟通、治理参与、现场核查等途径相互补充，需验证信息质量。','仅依赖创始人一句“一切正常”是否充分？','不充分，应结合证据与监测','充分，口头保证永远可靠','充分，熟人无需核查','充分，企业名称知名'],
['增值服务','战略、人才、业务资源和融资等支持可帮助企业发展，但不保证成功。','提供增值服务会保证企业盈利吗？','不会，仍受执行和经营风险影响','会，服务等于兜底','会，资本自动增长','会，政策必定保护收益'],
['并购整合','并购投后关注协同、治理与经营整合等，整合过程本身可能带来风险。','并购宣称有协同效应，投后需要验证什么？','协同落实与整合效果','只看签约照片','只看购买金额','协同无需执行']]);
unit('上市退出：上市与变现不是同一刻',3,'7.1,7.2','企业上市成功，基金却未必能立即全部出售股份。股份转让还受适用规则和市场条件影响。','房子拿到产权证，不等于当天找到买家收齐房款。',[
['退出目的','退出把投资权益转换为相应回收，时间、价格与费用会影响最终回报。','分析退出回报，应考虑哪些因素？','回收金额、时间与成本','只看账面估值','只看企业名称','只看出资人数'],
['境内上市','境内上市须满足适用市场与发行上市条件，不应把申请看成成功保证。','提交上市申请是否等于已成功上市？','不等于，还需相应程序与条件','等于，申请可立即出售','等于，价格固定','等于，所有投资者自动退出'],
['境外上市','境外上市涉及相关市场与跨境要求，规则不能与境内无条件混用。','比较境内外上市时，正确做法是？','分别核对市场条件与适用要求','认为所有市场规则完全相同','只比较地名长度','只看宣传语言'],
['上市后转让','上市后股份转让还需考虑锁定、减持、交易机制等适用要求和市场流动性。','成功上市后一定能立即全额变现吗？','不一定，还受规则和交易条件约束','一定，上市即现金到账','一定，管理人决定价格','一定，费用不存在']]);
unit('挂牌、协议转让、回购与清算',3,'7.3,7.4,7.5','企业未上市，基金寻找买方，或依据文件讨论回购；经营失败时也可能进入清算。不同路径不能混淆。','出售整件物品、依约退回或拆解处理，程序与回收不同。',[
['挂牌路径','全国股转系统挂牌有相应条件与流程；挂牌与交易流动性并不等同。','挂牌后是否保证随时找到买方？','不保证，还需看交易条件与流动性','保证，价格可任意指定','保证，挂牌就是保本','保证，不需要任何交易规则'],
['第三方转让','协议转让需寻找买方、协商价格与条款，并履行相关程序。','第三方愿意接手股权，仍需关注什么？','价格、文件、权利与适用程序','只看买方口头承诺','无需核查任何条件','资产会自动转移'],
['回购退出','回购能否实现取决于条款、效力、条件与义务人履约能力等。','回购义务人缺乏支付能力，会影响什么？','实际回收与退出实现','完全不影响收益','基金必定立即获赔','自动由所有投资者垫付'],
['清算退出','企业清算涉及依法处理财产、债务与剩余权益，股权投资者不当然优先于所有债权人。','企业清算时，股东能先于所有债权人任意取回出资吗？','不能，应依法处理清偿与剩余分配','能，股权优先于全部债权','能，基金名字含私募即可','能，认缴额等于剩余资产']]);
unit('基金治理：公平与制衡',3,'8.1,8.2,8.3','基金面对关联交易和不同投资者利益。规则需要明确谁决定、怎样披露、如何管理冲突。','共同项目不只是选负责人，还需要公平的规则和监督。',[
['治理体系','治理关注权利、责任、决策、激励与约束的体系，依组织类型而异。','治理与简单业务操作的区别在哪里？','治理涉及权责和决策制衡机制','治理只是账户转账','治理只负责宣传','治理不涉及投资者'],
['利益一致','利益一致与公平对待投资者要求识别激励和冲突，不可仅为少数人利益牺牲他人。','管理人把利益只留给特定关系投资者，应关注什么？','公平对待与利益冲突问题','提高全部投资者收益','只需基金年限足够','只需文件保密'],
['审慎透明','专业审慎与信息透明支持有依据的决策和知情监督，并不等于公开所有商业秘密。','信息透明是否意味着应向公众披露所有敏感资料？','不意味着，应按义务、范围与保密要求处理','意味着全部文件必须公开','意味着客户数据可转卖','意味着可以忽略法定披露'],
['组织差异','公司、合伙与契约基金的内部治理安排不同，利益相关者参与机制应依法依约。','不同组织类型的治理能机械套用完全相同规则吗？','不能，应结合法律基础与合同','能，只看管理人数','能，所有投资者权力完全相同','能，品牌名称相同即可']]);
unit('权益登记与托管安排',3,'9.1,9.2','投资者姓名、出资与份额变更需要正确记录；基金托管与非托管情况下的安全措施也需依法依约判断。','共同仓库需要知道东西属于谁，也需要清楚由谁保管。',[
['权益登记','设立、变更与清算登记需匹配组织形式和相应程序，错误记录会影响权利识别。','基金权益转让后，为什么需处理相应登记？','准确反映权利变化并遵循程序','只为扩大宣传','所有权益无需记录','口头说过就永不变更'],
['托管意义','托管支持财产保管等职责与相应监督，但不承担投资收益保证。','托管报告能作为本金担保书吗？','不能，职责与收益保证不同','能，报告证明不会亏','能，托管人决定退出价格','能，所有损失由银行承担'],
['托管要求','股权基金托管与未托管安排须按适用规则及合同判断，不能笼统认定所有情形相同。','学习托管要求时，正确做法是？','核对适用规则、合同与安全措施','只背“所有情况完全一样”','由销售任意决定无需披露','只看基金规模'],
['信息与交接','托管职责、报告与交接安排需明确，机构更换不应导致财产与记录失控。','托管机构更换时最重要的关注之一是？','资产、资料与职责的规范交接','替换网站照片','增加基金简称','删除持有人档案']]);
unit('业绩指标：回了多少，剩下多少？',3,'9.3','出资100，已分配40，剩余价值80。三种倍数回答不同问题；IRR还考虑现金流的时间。','一个看已收获，一个看剩余果实，一个看总量；时间还影响价值。',[
['DPI','已分配倍数DPI＝累计分配／累计实缴，反映已回收部分。','实缴100、分配40，DPI为？','0.4','1.4','0.8','2.5'],
['RVPI与TVPI','RVPI＝剩余价值／实缴；TVPI＝DPI＋RVPI。口径必须一致。','实缴100、已分配40、剩余80，TVPI为？','1.2','0.4','0.8','3'],
['IRR','IRR是使现金流净现值为零的折现率，对现金流时点敏感，不应只比较总倍数。','投入100，一年后收回110，无其他现金流，IRR为？','10%','110%','1%','0%'],
['估值核算','账户功能、估值原则、核算与财务报告需保持一致；未实现估值不等同现金分配。','剩余价值升高是否等于DPI自动增加？','不是，DPI取决于实际分配','是，账面变现自动发生','是，任何估值都等于现金','是，实缴可不用记录']]);
unit('税收：先确认谁纳什么税',3,'9.4','同一笔业务可能涉及基金、投资者和管理人，税种与纳税规则依主体、收入和组织形式等不同。','一笔账先分清谁收到什么，再看如何处理。',[
['主体划分','税务分析先识别基金自身、投资者、管理人及收入性质，不能用一个税率覆盖所有层面。','计算基金相关税收，第一步应是什么？','识别主体、收入与适用规则','直接套一个常见税率','只看基金名称','先把所有主体混为一人'],
['组织与所得','不同组织形式及投资者身份可能影响所得税处理，具体税率、扣除和义务需核对原文。','公司型与合伙型税务能无条件完全混用吗？','不能，应确认组织形式与主体','能，只要总收益相同','能，只要管理人相同','能，只要基金规模相同'],
['优惠条件','创投税收优惠有投资对象、期限等条件，不能只凭基金名称认定优惠。','名字写“创投”，就自动符合全部税收优惠吗？','不自动，应核对具体资格与条件','自动，名称决定税收','自动，亏损可免税所有收入','自动，任意投资都优惠'],
['简化计算','训练数字可以用于理解税额计算，但税基、税率和抵扣须给定明确假设，不能作为普遍法定结论。','假设税基100、题目给定税率5%，不考虑其他因素，税额是多少？','5','95','105','0.05']]);
unit('收益分配、资本账户与基金清算',3,'9.5,9.6','项目赚了钱，钱怎么在返还本金、约定收益与业绩报酬之间分配？投资者转让份额，与基金卖出项目也不同。','共同经营收益要按协议分账；退出共同项目与项目出售资产是不同事情。',[
['分配顺序','收益分配应依法依约，返本、门槛收益、追补及分成等需要看具体约定，不可假设所有基金一致。','计算分配，首先应明确什么？','具体条款、顺序与计算口径','只看宣传年化收益','固定用任意20%','把全部收益归管理人'],
['分配方式','整体基金分配与逐项目分配在计算基础和激励约束等方面不同，应关注回拨等相关安排。','逐项目和整体基金分配能不区分直接混算吗？','不能，基础与安排不同','能，任何项目都等于全部基金','能，时间没有影响','能，费用永不参与计算'],
['资本账户','资本账户记录出资、分配及收入费用亏损分摊等权益变化，不能只记录募集额。','资本账户为什么不能只记录最初出资？','还需反映分配与损益等变化','因为最初出资没有意义','因为所有账户只记广告费','因为账面无需与权益联系'],
['退出与清算','投资者份额退出、基金项目退出和基金清算是不同层面；实物分配需满足适用条件。','投资者转让基金份额，等于基金卖出被投企业吗？','不等于，是不同层面的退出','等于，两者自动同步','等于，基金必须清算','等于，托管人必须买入']]);
unit('披露、报送与争议解决',3,'9.7,9.8','客户没有收到重大事项通知，又对费用有争议。你需要区分对投资者披露、监管报送和争议处理。','给参与者的项目报告，与报给主管单位的材料，接收人和目的不同。',[
['披露与报送','信息披露面向相应投资者，信息报送面向监管或自律主体等，二者不能当然替代。','向协会报送信息，就自动等于向投资者披露了吗？','不等于，应分别履行适用义务','等于，接收人无区别','等于，投资者无需知情','等于，任何文件都相同'],
['2026新规','2026信息披露实施细则自9月1日起施行，学习应确认正式版本与适用要求，避免沿用废止规范。','复习私募披露时，更合适的做法是？','核对正式2026规范与施行状态','只用2016旧规则不核对','把征求意见稿当最终版本','只看销售宣传'],
['争议方式','协商、调解、仲裁和诉讼各有法律基础与程序，仲裁等应看有效协议与适用条件。','有争议时能任意忽略有效争议解决条款吗？','不能，应核对条款与相应法律程序','能，按个人情绪选择','能，管理人可自行作终局裁判','能，销售可以取消司法程序'],
['争议证据','募集、风险告知、费用、估值、管理与分配等可能成为争议点，文件和履职记录很重要。','为何需要保存履职与交易记录？','支持权利义务核查与争议处理','只为增加文件数量','保存会自动免除责任','记录可以代替真实履职']]);
export const advancedLessons=courses.map((c,i)=>{const id=i+12;const [head,body]=c.points[0];return {id,title:c.title,subject:c.subject,area:'科目'+(c.subject===1?'一':'三'),sections:c.sections,goal:body,modes:[c.scene,c.analogy,c.points.map(p=>p[0]+'：'+p[1]).join('\n\n')],nodes:[c.points[0][0],c.points[1][0],c.points[2][0]],prompt:'如果有人只看表面结论，你会怎样解释“'+c.title+'”背后的原因和边界？',rubric:c.points.slice(0,2).map(p=>p[1]).join(' '),criteria:c.points.slice(0,2).map(p=>p[0]),details:c.points.map(p=>({title:p[0],text:p[1]})),questions:c.points.map((p,j)=>({key:'u'+id+'q'+j,id,subject:c.subject,prompt:p[2],options:p.slice(3,7),answer:0,explain:p[1]})),options:c.points[0].slice(3,7),answer:0,explain:body};});
